                    "pair": pair_name,
                    "group": group,
                    "name": name,
                    "valid": valid,
                    "weight": weight,
                    "share": _round_output(share_value),
                    "contribution": [
                        _round_output(coverage_value),
                        _round_output(change_value),
                    ],
                    "uncertainty": _round_output(uncertainty_value),
                    "rank": ranks[name],
                }
